from pathlib import Path
import subprocess
nl=chr(10)
p=Path('control/hourly/bootstrap_run.py')
L=['from pathlib import Path','from datetime import datetime','import importlib.util','import json','','ROOT = Path(__file__).resolve().parents[2]','','def load_manifest_module():','    path = ROOT / "control/hourly/run_manifest.py"','    spec = importlib.util.spec_from_file_location("run_manifest", path)','    mod = importlib.util.module_from_spec(spec)','    spec.loader.exec_module(mod)','    return mod','','def bootstrap():','    mod = load_manifest_module()','    manifest_path, data = mod.create_manifest()','    report = ROOT / "hourly-reports" / (data["run_id"] + ".md")','    if not report.exists():','        lines = [','            "# Hourly Research Report",','            "",','            "Run: " + data["run_id"],','            "Started: " + data["started_at"],','            "",','            "## Run metadata",','            "Status: STARTED",','            "",','            "## Source coverage",','            "PENDING",','            "",','            "## New evidence",','            "PENDING",','            "",','            "## Candidate hypotheses",','            "UNPROVEN",','            "",','            "## Negative evidence",','            "PENDING",','            "",','            "## Falsification",','            "PENDING",','            "",','            "## Reproduction",','            "PENDING",','            "",','            "## Coverage gaps",','            "PENDING",','            "",','            "## Incidents",','            "NONE YET",','            "",','            "## Decision",','            "NO_PROVEN_EDGE",','            "",','            "## Next hour",','            "PENDING",','        ]','        report.parent.mkdir(parents=True, exist_ok=True)','        report.write_text(chr(10).join(lines) + chr(10))','    return manifest_path, report, data','','if __name__ == "__main__":','    m, r, d = bootstrap()','    print(json.dumps({"ok":True,"run_id":d["run_id"],"manifest":str(m.relative_to(ROOT)),"report":str(r.relative_to(ROOT))}, sort_keys=True))']
p.write_text(nl.join(L)+nl)
r=lambda a:subprocess.run(a,capture_output=True,text=True,check=False)
c=r(['python3','-m','py_compile',str(p)]);d=r(['git','diff','--check']);ok=c.returncode==0 and d.returncode==0
out='ok='+str(ok)
if ok:
 r(['git','add',str(p)]);cm=r(['git','commit','-m','build(hourly): add run bootstrap and report skeleton']);ps=r(['git','push','origin','HEAD:main']);out += ' commit='+str(cm.returncode)+' push='+str(ps.returncode)
print(out)